if (typeof width === 'undefined') { var width = 1280; }
if (typeof height === 'undefined') { var height = 720; }

var verdigrisSplatters = [];
var numSplatters = 120;
var verdigrisPalette = ['#2a9d8f', '#264653', '#cd7f32', '#e76f51', '#1d3557'];

function setup() {
    createCanvas(windowWidth, windowHeight);
    background(18, 20, 22);
    for (var i = 0; i < numSplatters; i++) {
        verdigrisSplatters.push({
            x: random(width),
            y: random(height),
            r: random(4, 30),
            colStr: verdigrisPalette[floor(random(verdigrisPalette.length))]
        });
    }
}

function draw() {
    fill(18, 20, 22, 40);
    rect(0, 0, width, height);

    var beat = (window.beatEnergy || 0.0);
    var low = (window.audioLow || 0.5);
    var t = frameCount * 0.015;

    noStroke();
    for (var i = 0; i < verdigrisSplatters.length; i++) {
        var s = verdigrisSplatters[i];
        fill(s.colStr);
        circle(s.x + sin(t) * 5, s.y + cos(t) * 5, s.r * (1.0 + low * 0.4));
    }

    push();
    translate(width / 2, height / 2);
    var scaleVal = 1.0 + beat * 0.25;
    scale(scaleVal);

    stroke('#cd7f32');
    strokeWeight(4 + low * 3);
    noFill();

    var eyeDist = 140;
    var eyeSize = 70 + low * 30;
    ellipse(-eyeDist, -20, eyeSize * 1.3, eyeSize);
    fill('#ffb703');
    circle(-eyeDist, -20, 24);
    noFill();

    ellipse(eyeDist, -20, eyeSize * 1.3, eyeSize);
    fill('#ffb703');
    circle(eyeDist, -20, 24);
    noFill();

    stroke('#2a9d8f');
    strokeWeight(5);
    bezier(-eyeDist, -eyeSize, -eyeDist - 80, -eyeSize - 100, -eyeDist + 40, -eyeSize - 160, -eyeDist - 30, -eyeSize - 200);

    bezier(eyeDist, -eyeSize, eyeDist + 80, -eyeSize - 100, eyeDist - 40, -eyeSize - 160, eyeDist + 30, -eyeSize - 200);

    stroke('#cd7f32');
    strokeWeight(3);
    rectMode(CENTER);
    rect(0, 30, 60, 100);
    line(-160, 110, 160, 110);
    line(-120, 140, 120, 140);
    pop();
}

function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
}
